/**
 * Cross-platform browser opening utility
 */
/**
 * Open a URL in the default browser (async; awaits the launch).
 */
export declare function openBrowser(url: string): Promise<void>;
/**
 * Open a URL in the default browser SYNCHRONOUSLY and detached, best-effort.
 *
 * For terminal error paths (e.g. the credit-block upsell) where the caller must
 * exit the process immediately after, via a synchronous `process.exit()`. The
 * async `openBrowser()` can't be used there: `import('open')` would not resolve
 * before the process exits. Here we `spawn` the OS opener detached + unref'd so
 * the launch survives the parent exiting on the very next line, and never throw
 * (the upgrade link is already printed, so opening is pure convenience).
 */
export declare function openBrowserDetached(url: string): void;
